// VALID: Pointers within the same allocation or object
struct Data { long l; int i; };
Data d;
bool guaranteed_order = (&d.l < &d.i); // True, based on struct layout rules

int arr[10];
int* p_mid = &arr[5];
int* p_end = arr + 10; // Pointer one past end
bool valid_cmp = (p_mid < p_end); // Guaranteed True

// UNPECIFIED: Pointers across separate allocations
int* p_a = new int;
int* p_b = new int;

// p_a < p_b is UNPECIFIED BEHAVIOR (Standard C++)
// Compiler often implements as direct address comparison (fastest path)
bool risk_cmp = (p_a < p_b);

delete p_a;
delete p_b;

